import json
d=json.load(open('q_out.json'))
def walk(o):
    if isinstance(o,dict):
        if 'faces' in o and isinstance(o['faces'],list): 
            for f in o['faces']: print(f.get('index'), round(f['area'],3), [round(c,3) for c in f['centroid']], f.get('plane_normal'), f.get('cylinder'))
        if 'parameters' in o and isinstance(o['parameters'],list):
            for p in o['parameters']: print({k:p.get(k) for k in ('name','expression','value','comment')})
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
